// Deriv Bot v2.0 - dbot.deriv.com Compatible
// Advanced Trading Bot with Prediction Engine

'use strict';

class DerivBotApp {
    constructor(config) {
        this.config = config || {};
        this.ticks = [];
        this.trades = [];
        this.stats = {
            totalTrades: 0,
            wins: 0,
            losses: 0,
            profit: 0,
            startTime: new Date()
        };
        this.isRunning = false;
        this.currentStrategy = 'match';
        this.winRate = 0.5;
        this.confidenceThreshold = parseFloat(config.confidenceThreshold || 65);
        this.predictionInterval = parseInt(config.predictionInterval || 3000);
        this.stake = parseFloat(config.stake || 10);
        this.duration = parseInt(config.duration || 60);
        this.symbol = config.symbol || 'FRXUSDJPY';
        this.tradeType = config.tradeType || 'digits_match';

        console.log('🚀 Deriv Bot v2.0 Initialized for dbot.deriv.com');
    }

    // Add tick data
    addTick(value) {
        this.ticks.push({
            value: parseInt(value),
            timestamp: new Date()
        });

        // Keep only last 1000 ticks
        if (this.ticks.length > 1000) {
            this.ticks.shift();
        }
    }

    // Calculate RSI (Relative Strength Index)
    calculateRSI(period = 14) {
        if (this.ticks.length < period) return 50;

        const values = this.ticks.slice(-period).map(t => t.value);
        let gains = 0, losses = 0;

        for (let i = 1; i < values.length; i++) {
            const diff = values[i] - values[i - 1];
            if (diff > 0) gains += diff;
            else losses -= diff;
        }

        const avgGain = gains / period;
        const avgLoss = losses / period;

        if (avgLoss === 0) return avgGain > 0 ? 100 : 50;

        const rs = avgGain / avgLoss;
        const rsi = 100 - (100 / (1 + rs));

        return Math.round(rsi * 100) / 100;
    }

    // Calculate EMA (Exponential Moving Average)
    calculateEMA(period = 20) {
        if (this.ticks.length < period) {
            if (this.ticks.length === 0) return 5;
            return this.ticks.reduce((sum, t) => sum + t.value, 0) / this.ticks.length;
        }

        const values = this.ticks.slice(-period).map(t => t.value);
        const multiplier = 2 / (period + 1);
        let ema = values[0];

        for (let i = 1; i < values.length; i++) {
            ema = values[i] * multiplier + ema * (1 - multiplier);
        }

        return Math.round(ema * 100) / 100;
    }

    // Calculate Stochastic Oscillator
    calculateStochastic(period = 14) {
        if (this.ticks.length < period) return { k: 50, d: 50 };

        const values = this.ticks.slice(-period).map(t => t.value);
        const lowest = Math.min(...values);
        const highest = Math.max(...values);

        if (highest === lowest) return { k: 50, d: 50 };

        const k = 100 * (values[values.length - 1] - lowest) / (highest - lowest);
        const d = k; // Simplified for dbot

        return { 
            k: Math.round(k * 100) / 100, 
            d: Math.round(d * 100) / 100 
        };
    }

    // Calculate ATR (Average True Range)
    calculateATR(period = 14) {
        if (this.ticks.length < period) return 1;

        const values = this.ticks.slice(-period).map(t => t.value);
        let sumTR = 0;

        for (let i = 1; i < values.length; i++) {
            sumTR += Math.abs(values[i] - values[i - 1]);
        }

        const atr = sumTR / period;
        return Math.round(atr * 100) / 100;
    }

    // Predict next digit
    predictNextDigit() {
        if (this.ticks.length < 10) {
            return {
                digit: 5,
                confidence: 50,
                strategy: 'match'
            };
        }

        try {
            const recentTicks = this.ticks.slice(-30).map(t => t.value);

            // Calculate indicators
            const rsi = this.calculateRSI(14);
            const stochastic = this.calculateStochastic(14);
            const ema = this.calculateEMA(20);
            const atr = this.calculateATR(14);

            // Count digit frequencies
            const digitCounts = {};
            for (let i = 0; i < 10; i++) {
                digitCounts[i] = recentTicks.filter(t => t === i).length;
            }

            // Calculate scores for each digit
            const scores = {};
            for (let digit = 0; digit < 10; digit++) {
                let score = 0;

                // RSI contribution (weight: 0.25)
                if (rsi > 70) {
                    score += (digit > 5 ? (10 - digit) : digit) * 0.25;
                } else if (rsi < 30) {
                    score += (digit < 5 ? digit : (10 - digit)) * 0.25;
                } else {
                    score += Math.abs(digit - Math.round(ema)) * 0.25;
                }

                // Stochastic contribution (weight: 0.25)
                if (stochastic.k > 80) {
                    score += (digit > 5 ? (10 - digit) : digit) * 0.25;
                } else if (stochastic.k < 20) {
                    score += (digit < 5 ? digit : (10 - digit)) * 0.25;
                } else {
                    score += Math.abs(digit - Math.round(ema)) * 0.25;
                }

                // Pattern frequency (weight: 0.30)
                score += digitCounts[digit] * 0.30;

                // Volatility (weight: 0.20)
                score += (1 - Math.min(atr / 5, 1)) * 0.20;

                scores[digit] = score;
            }

            // Find best prediction
            let bestDigit = 5;
            let bestScore = 0;
            for (let digit = 0; digit < 10; digit++) {
                if (scores[digit] > bestScore) {
                    bestScore = scores[digit];
                    bestDigit = digit;
                }
            }

            // Calculate confidence
            const totalScore = Object.values(scores).reduce((a, b) => a + b, 0);
            const confidence = totalScore > 0 ? (scores[bestDigit] / totalScore) * 100 : 50;

            // Auto-switch strategy
            const threshold = 52;
            if (this.winRate < (threshold / 100) && this.trades.length > 5) {
                this.currentStrategy = this.currentStrategy === 'match' ? 'differ' : 'match';
                console.log('⚡ Strategy switched to:', this.currentStrategy);
            }

            return {
                digit: bestDigit,
                confidence: Math.round(confidence * 100) / 100,
                strategy: this.currentStrategy,
                rsi: Math.round(rsi * 100) / 100,
                ema: Math.round(ema * 100) / 100,
                stochastic: stochastic
            };
        } catch (error) {
            console.error('Prediction error:', error);
            return {
                digit: 5,
                confidence: 50,
                strategy: this.currentStrategy
            };
        }
    }

    // Record trade result
    recordTradeResult(tradeResult) {
        this.trades.push(tradeResult);

        if (tradeResult.won) {
            this.stats.wins++;
            this.stats.profit += tradeResult.profit;
        } else {
            this.stats.losses++;
        }

        this.stats.totalTrades++;

        // Update win rate
        if (this.stats.totalTrades > 0) {
            this.winRate = this.stats.wins / this.stats.totalTrades;
        }

        console.log(`📊 Trade #${this.stats.totalTrades}: ${tradeResult.won ? '✅ WIN' : '❌ LOSS'} | Win Rate: ${(this.winRate * 100).toFixed(2)}%`);
    }

    // Get session statistics
    getSessionStats() {
        const duration = new Date() - this.stats.startTime;
        const hours = Math.floor(duration / 3600000);
        const minutes = Math.floor((duration % 3600000) / 60000);

        return {
            totalTrades: this.stats.totalTrades,
            wins: this.stats.wins,
            losses: this.stats.losses,
            winRate: (this.winRate * 100).toFixed(2) + '%',
            profit: this.stats.profit.toFixed(2),
            duration: `${hours}h ${minutes}m`,
            currentStrategy: this.currentStrategy,
            confidence: this.confidenceThreshold,
            predictionInterval: this.predictionInterval + 'ms'
        };
    }

    // Print summary
    printSummary() {
        const stats = this.getSessionStats();
        console.log('\n' + '='.repeat(60));
        console.log('📊 SESSION SUMMARY');
        console.log('='.repeat(60));
        console.log(`Total Trades: ${stats.totalTrades}`);
        console.log(`Wins: ${stats.wins} | Losses: ${stats.losses}`);
        console.log(`Win Rate: ${stats.winRate}`);
        console.log(`Total Profit: $${stats.profit}`);
        console.log(`Duration: ${stats.duration}`);
        console.log(`Strategy: ${stats.currentStrategy}`);
        console.log('='.repeat(60) + '\n');
    }

    // Start bot
    start() {
        this.isRunning = true;
        console.log('🎯 Bot started for dbot.deriv.com');
        return {
            status: 'running',
            timestamp: new Date().toISOString(),
            config: {
                symbol: this.symbol,
                stake: this.stake,
                duration: this.duration,
                tradeType: this.tradeType,
                confidenceThreshold: this.confidenceThreshold
            }
        };
    }

    // Stop bot
    stop() {
        this.isRunning = false;
        this.printSummary();
        console.log('⏹️ Bot stopped');
        return this.getSessionStats();
    }

    // Main prediction loop
    runPredictionCycle() {
        if (!this.isRunning) return null;

        const prediction = this.predictNextDigit();

        if (prediction.confidence >= this.confidenceThreshold) {
            return {
                action: 'TRADE',
                digit: prediction.digit,
                strategy: prediction.strategy,
                tradeType: prediction.strategy === 'match' ? 'DIGITMATCH' : 'DIGITDIFF',
                confidence: prediction.confidence,
                stake: this.stake,
                duration: this.duration,
                symbol: this.symbol,
                timestamp: new Date().toISOString()
            };
        }

        return {
            action: 'WAIT',
            reason: 'Confidence too low',
            confidence: prediction.confidence,
            threshold: this.confidenceThreshold,
            timestamp: new Date().toISOString()
        };
    }
}

// Export for dbot.deriv.com
if (typeof module !== 'undefined' && module.exports) {
    module.exports = DerivBotApp;
}

// For direct execution
if (typeof window === 'undefined' && require.main === module) {
    // Node.js environment
    const config = {
        symbol: process.env.SYMBOL || 'FRXUSDJPY',
        stake: parseFloat(process.env.STAKE || 10),
        duration: parseInt(process.env.DURATION || 60),
        tradeType: process.env.TRADE_TYPE || 'digits_match',
        confidenceThreshold: parseFloat(process.env.CONFIDENCE || 65),
        predictionInterval: parseInt(process.env.PREDICTION_INTERVAL || 3000)
    };

    const bot = new DerivBotApp(config);
    bot.start();
    console.log(bot.getSessionStats());
}
